<?php
// Isolated existing loopback fixture; restore the deliberately varied source price afterwards.
define('WP_ADMIN',true);require '/var/www/html/wp-load.php';if(wp_parse_url(home_url(),PHP_URL_HOST)!=='127.0.0.1')exit(2);wp_set_current_user(1);$checks=[];$created=[];$source=vpm_affiliate_source_page('preise');$original=$source->post_content;$profile=get_option('vpm_site_profile',null);
function apcheck($v,$label){global $checks;if(!$v)throw new Exception($label);$checks[]=$label;}
try{
 $content=str_replace('89,99 €','100,49 €',$original);wp_update_post(['ID'=>$source->ID,'post_content'=>$content]);$before=hash('sha256',get_post_field('post_content',$source->ID));
 $r=vpm_prepare_affiliate_preview();if(is_wp_error($r))throw new Exception($r->get_error_message());$created=array_merge(array_values($r['pages']),$r['providers']);apcheck(hash('sha256',get_post_field('post_content',$source->ID))===$before,'Preview leaves current published source unchanged');apcheck(count($r['providers'])===9&&count($r['pages'])===3,'Nine provider copies and three page copies are prepared');foreach($created as $id)apcheck(get_post_status($id)==='draft','Prepared object '.$id.' remains a draft');
 $newLink=json_decode(file_get_contents(WP_PLUGIN_DIR.'/vpm-content-drafts/updates/affiliate-2026-11.json'),true)['affiliate_url'];$new=0;foreach($r['providers']as $id){$name=get_the_title($id);if($name==='Park Drive Fly')apcheck(get_post_meta($id,'_vpm_price',true)==='ab 100,49 € für 8 Tage','Current source price wins over older fallback without rounding cents');$url=get_post_meta($id,'_vpm_parkenamflughafen_url',true);if($url){++$new;apcheck($url===$newLink&&get_post_meta($id,'_vpm_rating',true)==='','New partner has exact approved URL and no invented rating');}}
 apcheck($new===3,'Exactly three new affiliate cards');$prices=get_post_field('post_content',$r['pages']['preise']);preg_match('~<tbody>(.*?)</tbody>~s',$prices,$b);preg_match_all('~<tr>.*?</tr>~s',$b[1],$rows);$cents=array_map(fn($row)=>vpm_affiliate_price_number(vpm_affiliate_price_cells($row)[1]),$rows[0]);$sorted=$cents;sort($sorted);apcheck($cents===$sorted&&count($cents)===10,'Price table preserves airport row and sorts all ten offers by price');apcheck(substr_count(html_entity_decode($prices),$newLink)===3,'Each new table CTA keeps the approved tracking link');
 $safety=get_post_field('post_content',$r['pages']['valet-parken-sicherheit']);apcheck(substr_count(html_entity_decode($safety),$newLink)===3,'Three approved security CTAs');apcheck(str_contains($safety,'Schrankenanlage und Videoüberwachung')&&str_contains($safety,'Tankfüllung'),'Approved safety details retained');
 apcheck(vpm_affiliate_price_label(17490)==='174,90 €'&&vpm_affiliate_price_label(17400)==='174 €','Euro formatting preserves cents and whole-euro approved prices');
 wp_set_current_user(0);apcheck(is_wp_error(vpm_prepare_affiliate_preview()),'Anonymous caller cannot prepare drafts');wp_set_current_user(1);update_option('vpm_site_profile',vpm_profile_preset('umbrella'));apcheck(is_wp_error(vpm_prepare_affiliate_preview()),'Munich offers cannot be imported on umbrella profile');
 file_put_contents('/tmp/vpm-affiliate-preview-report.json',wp_json_encode(['count'=>count($checks),'checks'=>$checks],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo count($checks)." affiliate preview checks passed\n";
}finally{wp_set_current_user(1);wp_update_post(['ID'=>$source->ID,'post_content'=>$original]);foreach(array_reverse($created)as $id)wp_delete_post($id,true);if($profile===null)delete_option('vpm_site_profile');else update_option('vpm_site_profile',$profile);}
